:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c63ff;
  --accent: #ffd166;
  --text: #f0f0f5;
  --card-back: #3a3a55;
  --card-back-hover: #4a4a6a;
  --matched: #2e7d32;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 4px;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c0;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  gap: 12px;
}

.moves {
  font-size: 1.1rem;
  font-weight: 600;
}

#newGameBtn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  min-height: 44px;
  border: none;
  border-radius: var(--radius);
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#newGameBtn:hover {
  background: #5a52e0;
}

#newGameBtn:active {
  transform: scale(0.96);
}

#newGameBtn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.win-message {
  text-align: center;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--accent);
  padding: 12px;
  margin-bottom: 16px;
  background: rgba(255, 209, 102, 0.1);
  border-radius: var(--radius);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: var(--radius);
  background: var(--card-back);
  cursor: pointer;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  transition: background 0.2s, transform 0.1s;
  padding: 0;
  overflow: hidden;
}

.card:hover {
  background: var(--card-back-hover);
}

.card:active {
  transform: scale(0.95);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card.flipped,
.card.matched {
  color: #fff;
  cursor: default;
}

.card.matched {
  box-shadow: inset 0 0 0 3px var(--matched);
  cursor: default;
}

.card:disabled {
  cursor: default;
}

.card:disabled:hover {
  background: inherit;
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
  }
  :root {
    --gap: 8px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .status-bar {
    flex-direction: column;
    align-items: stretch;
  }
  #newGameBtn {
    width: 100%;
  }
}

@media (max-width: 360px) {
  body {
    padding: 8px;
    font-size: 16px;
  }
  .game-container {
    padding: 12px;
  }
  .game-board {
    grid-template-columns: repeat(4, 1fr);
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
    '#9b5de5', '#f15bb5', '#00bbf9', '#fee440'
  ];

  const board = document.getElementById('gameBoard');
  const moveCountEl = document.getElementById('moveCount');
  const winMessage = document.getElementById('winMessage');
  const newGameBtn = document.getElementById('newGameBtn');

  let deck = [];
  let flipped = [];
  let matchedCount = 0;
  let moves = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function buildDeck() {
    const cards = [];
    COLORS.forEach((color, idx) => {
      cards.push({ id: idx, color });
      cards.push({ id: idx, color });
    });
    return shuffle(cards);
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((card, index) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card';
      btn.dataset.index = index;
      btn.dataset.id = card.id;
      btn.style.backgroundColor = '';
      btn.setAttribute('aria-label', 'Hidden card ' + (index + 1));
      btn.addEventListener('click', onCardClick);
      board.appendChild(btn);
    });
  }

  function onCardClick(e) {
    const btn = e.currentTarget;
    if (lock || btn.classList.contains('flipped') || btn.classList.contains('matched')) {
      return;
    }
    flipCard(btn);
    flipped.push(btn);

    if (flipped.length === 2) {
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function flipCard(btn) {
    const card = deck[Number(btn.dataset.index)];
    btn.classList.add('flipped');
    btn.style.backgroundColor = card.color;
    btn.textContent = '';
    btn.setAttribute('aria-label', 'Card ' + (Number(btn.dataset.index) + 1) + ' revealed');
  }

  function checkMatch() {
    const [a, b] = flipped;
    if (a.dataset.id === b.dataset.id) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.disabled = true;
      b.disabled = true;
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      matchedCount++;
      flipped = [];
      if (matchedCount === COLORS.length) {
        showWin();
      }
    } else {
      lock = true;
      setTimeout(() => {
        [a, b].forEach((btn) => {
          btn.classList.remove('flipped');
          btn.style.backgroundColor = '';
          btn.setAttribute('aria-label', 'Hidden card ' + (Number(btn.dataset.index) + 1));
        });
        flipped = [];
        lock = false;
      }, 700);
    }
  }

  function showWin() {
    winMessage.hidden = false;
    winMessage.textContent = 'You won in ' + moves + ' moves! 🎉';
  }

  function resetGame() {
    deck = buildDeck();
    flipped = [];
    matchedCount = 0;
    moves = 0;
    lock = false;
    moveCountEl.textContent = '0';
    winMessage.hidden = true;
    winMessage.textContent = '';
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
